          if(m.msg_type==='balance'&&m.balance){const b={balance:Number(m.balance.balance),currency:m.balance.currency||'USD',loginid:m.balance.loginid};if(startBalanceRef.current===null)startBalanceRef.current=b.balance;const pnl=b.balance-startBalanceRef.current;setState(s=>({...s,balance:b,pnl,error:null}));const be=document.getElementById('balance');if(be)be.textContent=`${b.currency==='USD'?'$':b.currency+' '}${b.balance.toFixed(2)}`;const pe=document.getElementById('pnl');if(pe){pe.textContent=`${pnl>=0?'+':''}$${pnl.toFixed(2)}`;pe.style.color=pnl<0?'#e24b4a':''}window.dispatchEvent(new CustomEvent('izitrader:balance',{detail:{...b,pnl}}))}
